    words = test.split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    if not frequency:
        return {}

    max_count = max(frequency.values())
    result = {k: v for k, v in frequency.items() if v == max_count}

